import type { EditorialSeedEntry } from './editorialSeedData';

const cover = '/assets/images/blog-og-image.webp';
type DraftSpec = {
  title: string; slug: string; query: string; categories: string[]; routes: string[];
  platforms?: string[]; meta: string; intro: string; body: string; decision: string; source: string;
};

function draft(spec: DraftSpec): EditorialSeedEntry {
  const guide = spec.routes.includes('guide');
  const comparison = spec.categories.includes('Comparativas');
  const ranking = spec.categories.includes('Rankings');
  const platformLinks = (spec.platforms || []).map((platform) => {
    const urls: Record<string, string> = {
      netflix: 'https://help.netflix.com/es-es/node/412',
      'prime-video': 'https://www.primevideo.com/help/?language=es-ES&nodeId=GD5REBNJD74BURF6',
      max: 'https://help.max.com/es-es/answer/detail/000002543',
      'disney-plus': 'https://www.disneyplus.com/es-es',
    };
    return urls[platform]
      ? `<a href="${urls[platform]}" rel="nofollow noopener">${platform}</a>`
      : platform;
  }).join(', ');
  const angle = comparison
    ? `<section><h2>La comparación que sí ayuda a decidir</h2><p>La comparación no se resuelve con un ganador universal. Para <strong>${spec.title}</strong>, el criterio correcto es cruzar la necesidad del lector con una evidencia que pueda comprobar: el partido concreto, el título disponible, el nivel de plan o el coste del mes. Las diferencias entre ${platformLinks || 'servicios'} solo son útiles cuando cambian la decisión. Por eso esta pieza separa datos verificables de interpretación editorial y evita sumar catálogos que usan definiciones distintas.</p><p>Hay tres errores que conviene evitar. El primero es contar como incluido un contenido que exige alquiler, compra o canal adicional. El segundo es trasladar a España una tarifa o derecho publicado para otro mercado. El tercero es convertir una promoción con fecha de fin en el precio normal. GuíaTV añade el cruce entre fuente externa y ficha local para que el lector pueda comprobar el resultado antes de pagar.</p></section>`
    : ranking
      ? `<section><h2>El criterio detrás de la selección</h2><p>Una selección editorial no es un carrusel de popularidad. Cada entrada debe justificar qué resuelve: una sesión corta, un género concreto, una historia para compartir o una serie que merece continuidad. En <strong>${spec.title}</strong>, la disponibilidad en España es una condición previa, no un detalle añadido al final. Si el título deja de estar en el catálogo, la recomendación pierde sentido aunque siga apareciendo en listas antiguas.</p><p>El orden también importa. Una lista útil empieza por el perfil de espectador y después presenta alternativas, con una razón que permita descartar o elegir. GuíaTV aporta el catálogo filtrable, la relación con otros servicios y una fecha de comprobación; el juicio editorial explica por qué una opción encaja mejor que otra.</p></section>`
      : `<section><h2>Cómo resolver la búsqueda en GuíaTV</h2><p>La respuesta cambia según el momento. En una emisión, la hora y el canal son determinantes; en streaming, lo son la disponibilidad y el tipo de acceso. Para <strong>${spec.title}</strong>, la ruta empieza en ${guide ? 'la programación y la agenda de GuíaTV' : 'el catálogo de GuíaTV'} y termina en la ficha que confirma el dato. Así se evita recomendar una emisión pasada, un episodio distinto o un título que solo aparece en otro territorio.</p><p>El contexto también forma parte de la respuesta. Una misma película puede funcionar para una sesión familiar y no para alguien que busca cine nocturno; un partido puede estar en un paquete que el usuario no tiene; un plan barato puede incluir anuncios o menos pantallas. La función editorial de GuíaTV es ordenar esas diferencias para que el lector tome una decisión informada.</p></section>`;
  const evidence = `<section><h2>Qué queda verificado y qué puede cambiar</h2><p>La fuente primaria confirma el dato que cambia; GuíaTV confirma cómo se presenta en España. Las páginas de ${platformLinks || 'los proveedores y titulares de derechos'} pueden modificar precio, catálogo, horario o condiciones sin cambiar la intención de búsqueda. Por eso no se incluyen cifras, nombres de títulos ni canales que no estén respaldados por una fuente identificable. Cuando falta una confirmación, se dice expresamente y se ofrece la ruta para volver a comprobarla.</p><p>Esta disciplina evita dos respuestas frecuentes pero poco fiables: copiar una nota de prensa como si fuera disponibilidad efectiva y tratar una base de datos internacional como si fuera una guía española. La fecha de verificación queda visible para que el lector y el editor sepan cuándo repetir la comprobación.</p></section>`;
  const articleSpecific = ARTICLE_SPECIFIC[spec.slug] || '';
  const depth = comparison
    ? `<section><h2>Cómo comparar sin pagar por una promesa</h2><p>El precio de entrada no es el coste de una experiencia equivalente. Hay que anotar si el plan incluye anuncios, qué resolución ofrece, cuántas reproducciones simultáneas permite y si las descargas están disponibles. Cuando un proveedor publica varios niveles, la comparación debe conservar esos nombres y no reducirlos a “básico” y “premium”, porque esa simplificación borra la diferencia que el lector necesita conocer. También hay que separar una suscripción directa de un paquete de operador: pueden compartir marca y catálogo, pero no necesariamente precio, permanencia o condiciones de cancelación.</p><p>La segunda capa es el catálogo. No tiene sentido declarar vencedor a un servicio porque enumera muchas películas si el usuario busca tres series que están en el rival. GuíaTV aporta una comprobación reproducible: buscar los títulos prioritarios, filtrar por plataforma y revisar la ficha española. El resultado puede expresarse como una cesta de contenidos y no como una cifra total imposible de auditar. Si dos servicios cubren la misma necesidad, el desempate razonable es el coste mensual normal, la calidad del plan y la facilidad de cancelación, no una promoción que caduca.</p><p>Para una familia o un grupo conviene calcular el coste por persona solo cuando las condiciones permiten esas reproducciones. No se debe asumir que compartir cuenta entre hogares está permitido; la fuente del proveedor manda. Para un aficionado al deporte, además, la disponibilidad de una competición no garantiza todos los partidos. La comparación debe bajar al encuentro y al paquete concreto. Ese nivel de detalle es la diferencia entre un artículo de afiliación y una herramienta editorial que evita una compra equivocada.</p></section>`
    : ranking
      ? `<section><h2>De la lista al criterio editorial</h2><p>Un ranking útil ofrece más información que una colección de nombres. En primer lugar define a quién sirve: alguien que empieza en el género, quien busca una sesión de duración limitada o quien quiere una ficción para seguir durante semanas. Después explica qué evidencia activa la recomendación. La disponibilidad en GuíaTV es un filtro; el motivo de selección es el trabajo editorial. Por eso una entrada debe poder responder qué aporta, qué tipo de espectador puede descartarla y qué alternativa tiene sentido.</p><p>También conviene reconocer los límites. El catálogo español no es permanente, una tendencia de portada no equivale a calidad y la valoración internacional no garantiza que un título esté incluido en la suscripción. Cuando la fuente primaria no publica audiencia localizada, no se debe inventar una posición. La fecha de comprobación permite distinguir una selección actual de un archivo. En una revisión posterior, retirar un título que ha desaparecido es una mejora de calidad, no una pérdida de autoridad.</p><p>GuíaTV añade contexto operativo al ranking: relaciona el título con su plataforma, permite continuar hacia el catálogo y ofrece alternativas que responden a la misma necesidad. Eso evita que la pieza termine en una recomendación cerrada. El lector puede contrastar género, duración y servicio y tomar una decisión con menos pasos. La conclusión editorial debe ser una elección razonada, no una orden ni una afirmación de gusto presentada como hecho.</p></section>`
      : `<section><h2>Leer la programación con contexto</h2><p>La parrilla necesita interpretación porque una misma búsqueda reúne emisiones en directo, reposiciones, capítulos sueltos y títulos bajo demanda. GuíaTV permite empezar por la hora actual y avanzar hasta la siguiente emisión; ese recorrido es más útil que una lista fija publicada por la mañana. Para una sesión corta, la duración y el tiempo restante importan. Para una serie, importa saber si el capítulo es una reposición o el siguiente episodio. Para fútbol, el encuentro y la competición deben permanecer unidos a la información de emisión.</p><p>La programación también tiene límites que una guía honesta debe mostrar. Una hora puede cambiar, una emisión puede sufrir una modificación de última hora y un derecho deportivo puede aplicarse a un paquete concreto. La página no debe convertir esos casos en certeza permanente. El lector obtiene una respuesta mejor si se le dice qué está confirmado, qué debe revisar y dónde encontrar el dato más reciente. Ese método es especialmente importante en consultas móviles hechas justo antes de ver la televisión.</p><p>La aportación de GuíaTV está en unir descubrimiento y acción: el usuario puede pasar del horario al canal, de la ficha a una alternativa de streaming o de un partido a la competición. La pieza editorial explica cómo usar esos datos y qué decisión resuelven. No sustituye a la lectura viva; la hace comprensible y reduce el riesgo de llegar tarde, abrir un servicio equivocado o confundir una disponibilidad internacional con una española.</p></section>`;
  return {
    title: spec.title, slug: spec.slug, excerpt: spec.meta,
    contentType: spec.categories.includes('Comparativas') ? 'analysis' : 'guide',
    primaryIntent: spec.query, targetQuery: spec.query, relatedPlatformKeys: spec.platforms || [],
    relatedRouteKeys: spec.routes, faqItems: [], evergreen: !spec.categories.includes('Fútbol'),
    categories: spec.categories, coverImage: cover, metaTitle: spec.title, metaDescription: spec.meta,
    keywords: [spec.query], publishedAt: '2026-08-31T09:00:00.000Z',
    content: `<div class="editorial-body"><p>${spec.intro}</p>${articleSpecific}${ARTICLE_APPENDIX[spec.slug] || ''}${ARTICLE_APPENDIX_2[spec.slug] || ''}${ARTICLE_APPENDIX_3[spec.slug] || ''}<section><h2>La respuesta corta</h2><p>${spec.body}</p></section>${angle}${depth}${evidence}<section><h2>Qué haría un lector con esta información</h2><p>${spec.decision}</p><p>La siguiente acción es comprobar el dato en <a href="${guide ? '/programacion-tv/que-ver-hoy' : '/plataformas'}">${guide ? 'la programación de GuíaTV' : 'el catálogo de GuíaTV'}</a> y conservar solo las opciones que encajen con el tiempo, el presupuesto y el tipo de contenido buscado. Si el dato no aparece confirmado, no debe presentarse como definitivo.</p></section><section><h2>Fuentes y fecha de verificación</h2><p>${spec.source} Última investigación: <time datetime="2026-08-31">31 de agosto de 2026</time>. Autoría del borrador: Equipo editorial Guía TV; pendiente de revisión humana.</p></section></div>`,
  };
}

const ARTICLE_APPENDIX: Record<string, string> = {
  'netflix-vs-prime-video-espana': `<section><h2>La prueba que recomiendo antes de pagar</h2><p>Durante una semana, anota qué buscas realmente: una película concreta, una serie para varios días, una descarga para viajar o una compra ocasional. Si la mayoría de tus decisiones terminan en “incluido con Prime”, Prime Video puede tener sentido; si terminas saltando entre recomendaciones y originales de Netflix, la simplicidad de Netflix pesa más. La comparación no debe premiar una aplicación por mostrar más opciones de pago que la otra.</p><p>También hay una diferencia de salida. Netflix indica que se puede cambiar de plan o cancelar cuando se quiera, y sus cuentas están pensadas para personas que viven juntas. En Prime Video, Amazon aplica condiciones distintas a suscripciones, alquileres y compras. Antes de cancelar o rotar, conviene anotar qué contenidos se perderían y cuáles son compras permanentes. GuíaTV ayuda a mantener esa lista porque cada ficha enlaza la disponibilidad actual y evita depender de una captura antigua.</p></section>`,
  'netflix-vs-max-espana': `<section><h2>Cuándo no conviene pagar el plan superior</h2><p>El plan Premium solo aporta valor si el televisor, la conexión y los hábitos lo justifican. Netflix reserva 4K HDR y cuatro reproducciones para ese nivel; Max vincula el 4K, las cuatro reproducciones y hasta 100 descargas a Premium, con sus propias restricciones. Una pareja que ve una pantalla en Full HD no obtiene automáticamente una mejor experiencia por pagar esa diferencia. La recomendación responsable es comenzar por la cesta de títulos y después decidir resolución y pantallas.</p><p>Hay otro límite editorial: que una plataforma sea conocida por una saga no prueba que cada entrega siga allí. Las licencias cambian por país y fecha. Por eso la ficha de GuíaTV debe funcionar como control de la selección: título, plataforma española y fecha de consulta. Si el lector no encuentra uno de sus tres títulos principales, la conclusión debe cambiar aunque la plataforma pareciera ganadora al principio.</p></section>`,
  'max-vs-disney-plus-espana': `<section><h2>Familia, anuncios y convivencia</h2><p>El precio de Disney+ con anuncios no es comparable con un plan sin anuncios solo porque ambos permitan dos reproducciones. La página española informa de 1080p en los planes Estándar y Estándar con anuncios, mientras que Premium añade 4K HDR y cuatro reproducciones. También advierte que pueden existir promociones, patrocinios o publicidad en determinados contextos. Es un dato que una familia debe leer antes de convertir el precio de entrada en una recomendación.</p><p>En Max, el lector debe confirmar el proveedor de facturación y las condiciones de su plan. Si el acceso llega dentro de un paquete, la experiencia puede no coincidir exactamente con la suscripción directa. GuíaTV aporta la parte que las páginas de precios no resuelven: localizar títulos y alternativas en el catálogo español. Mi criterio es separar siempre tres decisiones: qué se quiere ver, cuántas personas lo verán y qué interrupciones o calidad se aceptan.</p></section>`,
  'movistar-plus-vs-dazn': `<section><h2>El cálculo mensual que evita contratar de más</h2><p>Para una competición concreta, cuenta los partidos que quedan en el calendario y los que verías de verdad. Después marca el operador que figura junto a cada encuentro en LaLiga. Si una sola noche determina la contratación, no tiene sentido pagar un paquete anual sin revisar permanencia, renovación y contenido complementario. Si el interés es semanal, compara el número de partidos de tu cesta, no el número total de deportes anunciados.</p><p>La agenda de GuíaTV debe conservar la hora local y el canal resuelto, pero la oferta comercial siempre debe leerse en Movistar Plus+ o DAZN antes de pagar. Un canal adicional, una señal en abierto y un servicio de streaming no son intercambiables. Este es el motivo por el que la guía enlaza el partido concreto y muestra una fecha de verificación: permite detectar un cambio de operador sin reciclar una tabla de una temporada anterior.</p></section>`,
  'mejores-plataformas-para-peliculas': `<section><h2>La lista corta que usaría para decidir</h2><p>Para cine de ciencia ficción, empezaría en Prime Video porque la consulta de GuíaTV devuelve Proyecto Salvación, Interstellar y Origen. Para una película de prestigio ampliamente reconocida, comprobaría Max con Cadena perpetua. Para animación de superhéroes, revisaría Spider-Man: un nuevo universo en Max. Netflix entra en la decisión con El caballero oscuro y los resultados actuales de su catálogo, pero no lo declararía ganador sin conocer la cesta del lector. La disponibilidad de un mismo título en más de un servicio es una oportunidad para comparar precio y calidad del plan.</p><p>El orden de esta selección no es una clasificación de calidad cinematográfica. Es una recomendación por uso: género, duración y posibilidad de empezar inmediatamente. Las fichas internas muestran año, sinopsis y plataforma; si falta la modalidad de acceso, el artículo debe decir “comprobar” y no “incluido”. Repetiría la consulta antes de actualizar esta página y retiraría cualquier título que desapareciera.</p></section>`,
  'mejores-plataformas-para-series': `<section><h2>Qué serie empezaría en cada servicio</h2><p>Para un drama completo y de largo recorrido, la muestra de GuíaTV favorece Netflix con Breaking Bad y House. Para fantasía y universos conectados, Max ofrece Juego de tronos y La casa del dragón. Para temporadas largas disponibles junto a otras opciones, Prime Video presenta Sobrenatural, Shameless y Smallville. En comedia y animación, Rick y Morty aparece tanto en Netflix como en Max, un buen caso para que el precio y el plan decidan. Estos ejemplos proceden de la consulta española del 31/08/2026, no de una lista perenne.</p><p>La mejor plataforma también depende del tiempo de recuperación. Si solo puedes ver dos episodios por semana, una temporada larga no es necesariamente mejor que una ficción corta. GuíaTV permite pasar de la recomendación a la ficha y consultar alternativas del mismo género; esa relación es el valor añadido frente a un ranking de popularidad. Al revisar la pieza, hay que comprobar especialmente si una serie aparece como incluida o con acceso adicional.</p></section>`,
  'mejor-plataforma-streaming-familias': `<section><h2>Una decisión por edades, pantallas y presupuesto</h2><p>Una familia con una sola televisión y niños pequeños puede preferir Disney+ Estándar con anuncios por el precio publicado de 6,99 €, siempre que acepte anuncios y 1080p. Dos personas que quieran ver contenido distinto a la vez deben comprobar las dos reproducciones del plan. Si hay cuatro espectadores y un televisor compatible, Disney+ Premium publica 4K HDR y cuatro reproducciones por 15,99 €, pero pagar ese nivel no tiene sentido si el equipo no lo aprovecha. En Netflix, el perfil infantil y los controles son parte de la decisión; en Prime Video, la distinción entre incluido y alquiler es crítica.</p><p>La prueba familiar consiste en preparar una lista de cinco títulos de edades diferentes en GuíaTV, revisar su clasificación y comprobar la plataforma española. El servicio que cubre solo una edad obliga a contratar un segundo catálogo o a rotar. La conclusión debe explicar esa limitación para que “familiar” no se convierta en una etiqueta vacía.</p></section>`,
  'streaming-por-menos-de-10-euros': `<section><h2>Qué se sacrifica al elegir la tarifa barata</h2><p>Disney+ ofrece el precio más bajo de esta comparación, 6,99 € al mes, pero el plan es con anuncios. Netflix cuesta 8,99 € con anuncios y ofrece 1080p y dos reproducciones según la información española consultada. En ambos casos, la cifra es mensual y puede cambiar; no se han convertido promociones de tres meses en precios ordinarios. Tampoco se cuenta un alquiler de Prime Video como suscripción por debajo de 10 €.</p><p>Para decidir, suma el coste de oportunidad: anuncios durante una película, un título bloqueado, una pantalla insuficiente o una calidad menor pueden hacer que el plan barato no resuelva la necesidad. Busca en GuíaTV tres títulos prioritarios y registra dónde aparecen. Si la cesta está en Disney+, el plan de 6,99 € es la primera opción; si está en Netflix, los 8,99 € pueden ser el coste más bajo para verla. La recomendación queda fechada y debe actualizarse cuando cambie cualquiera de esos datos.</p></section>`,
  'cuanto-cuesta-streaming-espana': `<section><h2>Qué se puede calcular con datos publicados</h2><p>Netflix publica tres precios mensuales en su página española: 8,99 € con anuncios, 14,99 € en Estándar y 21,99 € en Premium. Disney+ publica 6,99 € con anuncios, 10,99 € en Estándar y 15,99 € en Premium. Si se mantuvieran doce meses sin cambios, los totales serían 107,88 €, 179,88 € y 263,88 € para Netflix, y 83,88 €, 131,88 € y 191,88 € para Disney+. Son multiplicaciones orientativas, no contratos anuales: la fuente puede modificar precios y Disney+ dispone además de modalidades anuales.</p><p>Para Max no se inventa una cifra: su ayuda oficial dice que el precio varía según proveedor y plan. Para Prime Video tampoco se mezcla la membresía con alquileres, compras o add-ons, porque Amazon los cobra aparte. La tabla útil conserva “precio no fijado” cuando la fuente consultada no muestra una tarifa española estable.</p></section><section><h2>La cesta real importa más que el total</h2><p>Calcula primero una sola plataforma durante un mes. Después prueba una rotación de tres meses, contratando cada servicio solo cuando reúne los títulos prioritarios que GuíaTV confirma. Un hogar que necesita cuatro reproducciones no debe elegir el plan barato de dos solo por ahorrar; una persona que ve una pantalla tampoco necesita Premium automáticamente. Anota anuncios, resolución, descargas y cancelación junto al precio. Última verificación: 31/08/2026 con Netflix España, Disney+ España, ayuda de Max, ayuda de Prime Video y catálogo GuíaTV.</p></section>`,
  'estrenos-streaming-del-mes': `<section><h2>Estrenos de septiembre con fecha oficial</h2><p>La página oficial de estrenos de Netflix consultada el 31/08/2026 ya muestra una agenda concreta para España. El 1 de septiembre aparecen Al descubierto: Raygun, la breakdancer viral y Jared Freid: The Family Plan; el 2 llegan Mal de Amores y Punto de inflexión: Generación 11S; el 3 figuran Los caballeros, Gandhari y Fito Paez: El mundo cabe en una canción; el 4 se incorpora El páramo adolescente. Para la segunda semana, Fauda y DANG! están fechadas el 8, y El club gastronómico, La timonel y ¡Llama a mi agente!: La película el 10.</p><p>La selección responde a dos necesidades: quien quiere estrenos españoles puede empezar por Mal de Amores o El club gastronómico; quien prefiere una serie de continuidad debe comprobar Fauda; quien busca una película debe revisar Los caballeros, Gandhari o La timonel. Estos son títulos y fechas publicados por Netflix, no una promesa de que todas las fichas estén visibles en cada plan o dispositivo el minuto exacto del estreno.</p></section><section><h2>Cómo leer la fecha</h2><p>Netflix explica que sus originales suelen lanzarse a las 00:00, hora del Pacífico, aunque algunos episodios o emisiones tienen horario específico. GuíaTV sirve para comprobar la ficha española cuando llegue el día y para comparar la novedad con títulos ya disponibles. No se añaden estrenos de Prime Video, Max o Disney+ sin un calendario oficial equivalente: es preferible una agenda parcial verificable que una lista mensual completada con rumores. Revisión: 31/08/2026.</p></section>`,
  'mejores-peliculas-netflix-espana': `<section><h2>Tres películas que aparecen en la consulta española</h2><p>La búsqueda de películas en el catálogo GuíaTV del 31/08/2026 devuelve <strong>Intercambiados</strong>, <strong>La captura</strong> y <strong>El caballero oscuro</strong> entre los resultados de Netflix. La recomendación no es que el lector vea las tres sin contexto: abre cada ficha para confirmar sinopsis, año, género y modalidad en la fecha de lectura. El valor editorial está en escoger según la sesión y en mostrar una alternativa si el título desaparece.</p><ul><li><strong>Intercambiados:</strong> primera opción para quien quiere probar una novedad que aparece en la selección actual de Netflix; comprueba la ficha antes de empezar.</li><li><strong>La captura:</strong> alternativa para quien busca una película distinta a una franquicia; la decisión debe apoyarse en la sinopsis y duración de GuíaTV.</li><li><strong>El caballero oscuro:</strong> opción de catálogo reconocible que también aparece en Prime Video y Max en la consulta; esa coincidencia permite comparar servicios antes de contratar Netflix solo por una película.</li></ul><p>No ordeno estos títulos por una supuesta popularidad universal. Los ordeno como punto de partida para tres comportamientos: estreno o novedad visible, descubrimiento y título compartido. La disponibilidad es la de la consulta fechada, no una garantía futura.</p></section><section><h2>Cómo evitar recomendaciones caducadas</h2><p>Antes de publicar o actualizar esta lista, busca cada título en GuíaTV, revisa la ficha de Netflix y confirma que el acceso no exige otra modalidad. Netflix explica que el catálogo cambia por región y licencias; si uno de los tres ya no aparece, se sustituye por otro resultado comprobado y se actualiza la fecha. Última comprobación: 31/08/2026.</p></section>`,
  'mejores-peliculas-prime-video-espana': `<section><h2>Qué películas devuelve GuíaTV en Prime Video</h2><p>La consulta de catálogo español del 31/08/2026 devuelve <strong>Proyecto Salvación</strong>, <strong>El caballero oscuro</strong>, <strong>Interstellar</strong> y <strong>Origen</strong> entre los resultados de Prime Video. Es una selección más útil que una lista copiada porque permite contrastar cada ficha en España. También muestra una coincidencia importante: El caballero oscuro aparece en Netflix y Max, mientras que las otras películas sirven para estudiar la amplitud de la oferta de Prime Video.</p><ul><li><strong>Proyecto Salvación:</strong> la elección para quien quiere empezar por una película de ciencia ficción incluida en la búsqueda; confirma el tipo de acceso.</li><li><strong>Interstellar:</strong> alternativa de ciencia ficción que comparte resultado con Max; compara el coste de la suscripción y la modalidad antes de reproducir.</li><li><strong>Origen:</strong> otra opción de ciencia ficción en la muestra, útil para una sesión de película conocida por el lector.</li><li><strong>El caballero oscuro:</strong> título común a varios servicios, adecuado para demostrar por qué no basta con encontrarlo dentro de la aplicación.</li></ul><p>Amazon distingue oficialmente entre contenido incluido con Prime, alquiler, compra y suscripciones add-on. Por eso este artículo no llama “gratis” a ninguna película sin comprobar la etiqueta de la ficha. GuíaTV aporta la disponibilidad y la sinopsis; Amazon aporta la modalidad de acceso.</p></section><section><h2>Mi recomendación de compra</h2><p>Si vas a ver varias películas del grupo, revisa cuáles están incluidas antes de pagar un alquiler individual. Si solo buscas un título concreto y aparece como alquiler, calcula ese precio por separado. La lista está verificada el 31/08/2026 y debe rehacerse si cambia el acceso.</p></section>`,
};

const ARTICLE_APPENDIX_2: Record<string, string> = {
  'cuanto-cuesta-streaming-espana': `<section><h2>Cómo presentar una comparación de precios sin engañar</h2><p>Una tarifa mensual, una tarifa anual y una promoción inicial responden a preguntas distintas. En la tabla principal conviene mostrar primero el precio que se renueva, después el coste de un año si se mantuviera y, por separado, el descuento anual publicado. No se debe calcular un ahorro con una promoción caducada ni sumar el alquiler de una película al precio de la suscripción. En Max y Prime Video, donde las fuentes consultadas remiten a proveedor, el artículo debe enlazar la página de contratación y marcar el dato como pendiente de confirmación.</p><p>Para un lector que alterna servicios, el cálculo más útil es el coste por mes de uso: tres meses a 8,99 € no significan que Netflix cueste 8,99 € todo el año si se cancela el resto. GuíaTV añade la cesta de títulos que activa la rotación. Esa metodología convierte una lista de tarifas en una decisión doméstica comprobable.</p></section>`,
  'estrenos-streaming-del-mes': `<section><h2>Qué debe contener una agenda mensual</h2><p>Cada entrada necesita título, plataforma, país de disponibilidad, fecha anunciada y estado de confirmación. Si una compañía solo ha anunciado una ventana y no una fecha, debe aparecer como “sin día confirmado”, nunca como estreno del mes. Si el título ya figura en la ficha de GuíaTV, la redacción puede distinguir entre fecha de llegada y disponibilidad actual. Si todavía no está, la página debe enlazar la fuente oficial y volver a revisarse el día del lanzamiento.</p><p>En septiembre, la agenda de Netflix ofrece fechas suficiente para una selección concreta, pero no permite inferir los calendarios de Max, Prime Video o Disney+. Mantener ese límite es una señal de confianza: la ausencia de un proveedor no se rellena con rumores. La fecha de esta comprobación es 31/08/2026.</p></section>`,
  'mejores-peliculas-netflix-espana': `<section><h2>Cómo elegir una película y no solo un nombre</h2><p>Para decidir entre los tres resultados, empieza por la duración y el tono que muestra la ficha de GuíaTV. Después comprueba si la película está incluida en Netflix España o si aparece con una restricción del plan con anuncios. El caballero oscuro merece una comparación adicional porque la búsqueda también lo devuelve en Prime Video y Max; si el lector ya paga uno de esos servicios, Netflix no aporta por sí solo una razón económica. Intercambiados y La captura se conservan como alternativas de la búsqueda actual, pero la recomendación se elimina si la ficha deja de resolver plataforma y acceso.</p><p>La página debe actualizarse con una nueva consulta, no con una fecha inventada. Esta selección se verificó el 31/08/2026.</p></section>`,
  'mejores-peliculas-prime-video-espana': `<section><h2>Incluido no significa encontrado</h2><p>La búsqueda del catálogo confirma títulos, pero la ayuda de Amazon define varias modalidades. Antes de llamar recomendación a Proyecto Salvación, Interstellar, Origen o El caballero oscuro, abre la ficha y mira si la etiqueta es “Incluido con Prime”. Si aparece un precio de alquiler o compra, esa película se puede ver desde Prime Video, pero no pertenece al mismo cálculo que una suscripción. Es una distinción pequeña en pantalla y grande en el coste final.</p><p>La lista se ordena por casos de uso y coincidencias de catálogo, no por una valoración que la fuente no haya publicado para España. Vuelve a comprobarla el 31/08/2026 o antes de cualquier actualización.</p></section>`,
  'mejores-peliculas-max-espana': `<section><h2>Películas que devuelve el catálogo de Max</h2><p>La consulta española de GuíaTV del 31/08/2026 devuelve <strong>Cadena perpetua</strong>, <strong>El caballero oscuro</strong>, <strong>El señor de los anillos: El retorno del rey</strong>, <strong>Interstellar</strong> y <strong>Pulp Fiction</strong> entre los resultados de Max. No son intercambiables: la primera opción sirve para drama, la segunda para acción de superhéroes, la tercera para fantasía, la cuarta para ciencia ficción y la quinta para cine criminal. La ficha de cada título es la que confirma sinopsis, año, clasificación y acceso en España.</p><table><thead><tr><th>Sesión</th><th>Título inicial</th><th>Qué aporta</th></tr></thead><tbody><tr><td>Drama</td><td>Cadena perpetua</td><td>Una opción de larga duración para quien busca una historia de prisión y amistad.</td></tr><tr><td>Fantasía</td><td>El retorno del rey</td><td>Una sesión extensa; conviene confirmar duración y si se quiere ver como parte de una trilogía.</td></tr><tr><td>Ciencia ficción</td><td>Interstellar</td><td>También aparece en Prime Video; compara acceso antes de contratar.</td></tr><tr><td>Crimen</td><td>Pulp Fiction</td><td>Elección adulta; revisa la clasificación de la ficha.</td></tr></tbody></table><p>El artículo no llama “mejor” a un título por aparecer en portada. Explica qué tipo de espectador puede disfrutarlo y qué coste editorial tiene: duración, saga, edad o coincidencia con otro servicio.</p></section><section><h2>Veredicto de catálogo</h2><p>Max es la primera plataforma que comprobaría para una noche de cine de catálogo, fantasía o ficción adulta. Si solo buscas Interstellar o El caballero oscuro, la coincidencia con otras plataformas obliga a comparar antes de pagar. La ayuda oficial de Max indica que los planes y precios varían según proveedor. Revisión: 31/08/2026.</p></section>`,
  'mejores-series-prime-video-espana': `<section><h2>Series concretas para empezar en Prime Video</h2><p>GuíaTV devuelve actualmente <strong>The Office</strong>, <strong>The Good Doctor</strong>, <strong>The Boys</strong>, <strong>Chicago P.D.</strong>, <strong>Chicago Fire</strong>, <strong>El mentalista</strong>, <strong>Ted Lasso</strong>, <strong>Sobrenatural</strong>, <strong>Yellowstone</strong> y <strong>Suits: la clave del éxito</strong> en la consulta de Prime Video. La variedad permite escoger por ritmo: comedia, drama médico, superhéroes, procedimental, western contemporáneo o ficción legal.</p><ul><li><strong>The Office:</strong> punto de partida para una comedia de episodios y personajes recurrentes.</li><li><strong>The Good Doctor:</strong> opción de drama médico para quien prefiere una continuidad larga.</li><li><strong>The Boys:</strong> ficción de superhéroes para público adulto; comprueba clasificación y acceso.</li><li><strong>Ted Lasso:</strong> alternativa de comedia y deporte, adecuada para una temporada de tono más amable.</li><li><strong>Yellowstone:</strong> drama serializado para quien acepta una historia de largo recorrido.</li></ul><p>Amazon distingue contenido incluido con Prime, alquiler/compra y canales add-on. El ranking solo es válido si la ficha confirma la modalidad elegida. GuíaTV añade las sinopsis, las alternativas y el filtro de plataforma, pero no congela la disponibilidad.</p></section><section><h2>Cómo elegir sin empezar una serie equivocada</h2><p>Decide primero si quieres una comedia episódica, un drama que exige continuidad o una ficción adulta. Después comprueba temporada y acceso en la ficha española. Mi recomendación general es The Office para una entrada ligera, Ted Lasso para una opción de tono deportivo y Yellowstone para una sesión serializada. Última verificación: 31/08/2026.</p></section>`,
  'mejores-series-max-espana': `<section><h2>La selección de Max por tipo de espectador</h2><p>La búsqueda de GuíaTV del 31/08/2026 muestra <strong>The Pitt</strong>, <strong>Rick y Morty</strong>, <strong>Los Soprano</strong>, <strong>Bajo escucha</strong>, <strong>Historias corrientes</strong>, <strong>Hora de aventuras</strong>, <strong>From</strong>, <strong>Juego de tronos</strong>, <strong>Friends</strong> y <strong>La casa del dragón</strong>. La lista permite distinguir novedades, animación, drama histórico de prestigio, terror y comedia de catálogo. Cada elección debe pasar por la ficha para comprobar la disponibilidad española y las temporadas.</p><table><thead><tr><th>Si quieres...</th><th>Empezaría por...</th><th>Motivo</th></tr></thead><tbody><tr><td>Drama actual</td><td>The Pitt</td><td>La ficha aparece en la consulta reciente; comprueba episodios y plan.</td></tr><tr><td>Drama de referencia</td><td>Los Soprano o Bajo escucha</td><td>Dos alternativas de catálogo para una sesión de varias temporadas.</td></tr><tr><td>Animación</td><td>Rick y Morty o Hora de aventuras</td><td>Perfiles de humor y público diferentes; revisa clasificación.</td></tr><tr><td>Fantasía</td><td>Juego de tronos o La casa del dragón</td><td>Conviene decidir si se quiere empezar por un universo completo.</td></tr></tbody></table><p>Max no se elige solo por una marca: gana cuando la cesta incluye varias series de esta selección. Su ayuda oficial separa Básico con anuncios, Estándar y Premium y advierte que los precios dependen del proveedor. No se atribuye aquí una tarifa sin confirmación.</p></section><section><h2>La recomendación editorial</h2><p>Para una serie nueva probaría The Pitt; para una maratón de catálogo, Los Soprano o Juego de tronos; para una sesión corta de animación, Rick y Morty. La disponibilidad se verificó en GuíaTV el 31/08/2026 y debe volver a comprobarse antes de publicar una actualización.</p></section>`,
  'que-ver-en-familia-este-fin-de-semana': `<section><h2>Una propuesta concreta para el fin de semana</h2><p>La respuesta familiar debe empezar por el tiempo disponible y no por una lista de estrenos. En la EPG de GuíaTV comprobada el 31/08/2026, La 1 ofrece <strong>El Grand Prix del Verano</strong> de 21:45 a 23:00 y después <strong>MasterChef</strong> hasta las 02:05; La 2 programa <strong>Los comancheros</strong> a las 22:35, durante 105 minutos. Son opciones diferentes: concurso para compartir sin seguir una trama, cine clásico con duración cerrada y un programa nocturno largo que no es apropiado para todos los menores.</p><p>En streaming, el catálogo consultado de GuíaTV devuelve alternativas que una familia puede revisar por edad y duración, pero la ficha de cada título debe confirmar clasificación y acceso. Disney+ publica planes con dos reproducciones en Estándar y cuatro en Premium; Netflix ofrece perfiles infantiles y controles. Esos datos ayudan a organizar la sesión, pero no sustituyen la lectura de la clasificación.</p></section><section><h2>Qué elegir según el grupo</h2><table><thead><tr><th>Grupo</th><th>Plan de partida</th><th>Por qué</th></tr></thead><tbody><tr><td>Adultos y niños mayores</td><td>Los comancheros en La 2</td><td>Película de 105 minutos y horario concreto; revisar la indicación ⑫.</td></tr><tr><td>Edades mezcladas y poco tiempo</td><td>El Grand Prix del Verano</td><td>Emisión de entretenimiento de 75 minutos, sin exigir una temporada previa.</td></tr><tr><td>Niños pequeños</td><td>Catálogo infantil con perfil controlado</td><td>Elegir después de consultar clasificación y disponibilidad en GuíaTV.</td></tr><tr><td>Familia que quiere maratón</td><td>Streaming, no EPG</td><td>Seleccionar episodios y pausas propias; comprobar pantallas del plan.</td></tr></tbody></table><p>Mi recomendación para una noche abierta es El Grand Prix del Verano si se busca una experiencia compartida y Los comancheros si el grupo acepta cine clásico. Si la edad no encaja, no se fuerza la elección: se vuelve a la ficha y se escoge una alternativa apta. La programación puede cambiar, por lo que esta guía lleva fecha y debe revisarse cada fin de semana.</p></section>`,
};

const ARTICLE_APPENDIX_3: Record<string, string> = {
  'mejores-peliculas-max-espana': `<section><h2>Qué descarto y por qué</h2><p>No presento una cifra de películas ni una clasificación global porque la consulta interna no permite comparar catálogos con el mismo criterio. Las coincidencias con Prime Video obligan a mirar el plan antes de contratar. La lista queda limitada a títulos resueltos en GuíaTV y a razones de sesión que el lector puede comprobar.</p></section>`,
  'mejores-series-prime-video-espana': `<section><h2>Una nota sobre la modalidad de acceso</h2><p>La presencia en la búsqueda de Prime Video no garantiza que una serie forme parte de la suscripción base. Amazon separa catálogo incluido, compra, alquiler y canales adicionales. Por eso la primera acción después de elegir The Office, Ted Lasso o Yellowstone es abrir la ficha y confirmar la etiqueta. Si cambia, se actualiza la recomendación y la fecha.</p></section>`,
  'mejores-series-max-espana': `<section><h2>Cómo mantener útil el ranking</h2><p>La selección debe retirarse o sustituirse cuando una serie deje de estar disponible en España. Max puede distribuirse directamente o mediante un proveedor, y su ayuda remite a la oferta aplicable. GuíaTV conserva el enlace al título y la alternativa del mismo género para que el lector no termine en una lista cerrada.</p></section>`,
  'que-ver-en-familia-este-fin-de-semana': `<section><h2>Regla de actualización</h2><p>Esta propuesta solo sirve para el fin de semana asociado a la verificación del 31/08/2026. Antes de publicarla de nuevo hay que consultar la EPG, cambiar las horas si la cadena las modifica y comprobar la clasificación de cualquier alternativa. El método es reutilizable; los títulos y horarios no.</p></section>`,
  'donde-ver-champions-league-en-espana': `<section><h2>Cuándo empieza y qué se puede confirmar</h2><p>La UEFA confirma que la fase liga de la Champions League 2026/27 comienza el 8 de septiembre de 2026 y termina el 27 de enero de 2027. Para la primera jornada aparecen partidos como Real Madrid-Inter el 8 de septiembre, Barcelona-Feyenoord el 9 y Liverpool-Atlético de Madrid el 9. Los horarios generales son las 21:00 HEC salvo excepciones; Barcelona-Feyenoord está señalado a las 18:45 HEC. En la comprobación del 31 de agosto todavía no existe un partido de Champions “hoy” en la EPG de GuíaTV: la respuesta correcta es una fecha próxima, no una emisión inventada.</p><p>La fuente de derechos consultada mantiene a Movistar Plus+ como referencia para el ciclo continental en España hasta 2026/27. Antes de publicar, hay que comprobar el canal y el paquete del operador para el encuentro concreto. La agenda de GuíaTV cruza la competición, el partido y el canal; la UEFA confirma calendario y hora.</p></section><section><h2>Cómo localizar el partido</h2><ol><li>Busca el club o el encuentro en la agenda de fútbol de GuíaTV.</li><li>Comprueba que la competición sea UEFA Champions League y no otra competición europea.</li><li>Contrasta fecha y hora con el calendario oficial de UEFA.</li><li>Revisa la oferta vigente de Movistar Plus+ u operador autorizado.</li></ol><p>El artículo no afirma que todos los partidos se emitan por el mismo canal si la fuente de derechos no lo detalla. También se evita trasladar horarios CET/HEC a España sin explicar la conversión. Última verificación: 31/08/2026.</p></section>`,
  'como-saber-que-ver-esta-noche': `<section><h2>Una decisión concreta para esta noche</h2><p>La EPG de GuíaTV del 31/08/2026 ofrece varias rutas sin obligar a abrir cinco aplicaciones. Si buscas una película en abierto, La 2 programa Los comancheros a las 22:35, con 105 minutos. Si quieres una serie, La 1 coloca Valle Salvaje a las 17:45 y La Promesa a las 18:35, mientras que Antena 3 reserva En tierra lejana para las 23:00 con una ventana de 195 minutos. Para entretenimiento compartido, El Grand Prix del Verano aparece en La 1 a las 21:45 durante 75 minutos. Son datos EPG con fecha, no recomendaciones reutilizables para mañana.</p><p>La recomendación cambia por el tiempo: cine de 105 minutos si quieres una sesión cerrada, una serie de 50–60 minutos si prefieres terminar pronto y el concurso si buscas ver la televisión sin seguir una trama. GuíaTV permite abrir la ficha, revisar edad, duración y canal y saltar a alternativas de catálogo cuando ninguna hora encaja.</p></section><section><h2>El filtro de tres preguntas</h2><ol><li>¿Quieres directo o bajo demanda?</li><li>¿Cuántos minutos puedes dedicar?</li><li>¿Qué edad y qué género deben encajar?</li></ol><p>Después limita la búsqueda a tres títulos. Si eliges streaming, confirma la plataforma española y el tipo de acceso; Prime Video, por ejemplo, distingue incluido, alquiler y compra. Si eliges televisión, comprueba que el programa no haya empezado y vuelve a mirar la hora antes de sentarte. La página se verificó el 31/08/2026 y debe actualizarse con cada nueva parrilla.</p></section>`,
};

const ARTICLE_SPECIFIC: Record<string, string> = {
  'peliculas-hoy-en-tv': `<section><h2>Las películas confirmadas en la parrilla de hoy</h2><p>La selección de esta fecha no sale de una lista internacional, sino de la respuesta EPG de GuíaTV para el 31 de agosto de 2026. La opción de cine más clara en la franja nocturna es <strong>Los comancheros</strong>, en La 2, con inicio previsto a las 22:35 y una duración de 105 minutos. Es una elección concreta para quien busca una película completa en abierto y prefiere el western clásico: el registro la identifica como cine, con año 1961 y calificación orientativa ⑫.</p><p>La guía también conserva emisiones cinematográficas que cruzan la medianoche o pertenecen al arrastre del día anterior. En La 1 figuran <strong>Kraven the Hunter</strong>, de 125 minutos, y <strong>Flash</strong>, de 130; el primero aparece con comienzo a las 22:00 y el segundo a las 00:05 en la referencia de emisión. No los presentamos como “la película de esta noche” sin explicar ese matiz: el lector debe abrir la ficha y comprobar si la hora corresponde a su zona y a la ventana de consulta.</p></section><section><h2>Cómo elegir según el tiempo disponible</h2><table><thead><tr><th>Necesidad</th><th>Opción de la EPG</th><th>Lectura editorial</th></tr></thead><tbody><tr><td>Cine en abierto y horario nocturno</td><td>Los comancheros · La 2 · 22:35</td><td>La alternativa más limpia para empezar y terminar dentro de la noche.</td></tr><tr><td>Acción y superhéroes</td><td>Flash · La 1 · referencia de madrugada</td><td>Solo conviene si se acepta acabar tarde y se confirma el horario.</td></tr><tr><td>Acción contemporánea</td><td>Kraven the Hunter · La 1 · referencia de noche</td><td>La ficha EPG aporta duración y edad; no debe confundirse con disponibilidad bajo demanda.</td></tr></tbody></table><p>La tabla no declara una película “mejor” por una puntuación aislada. Pone en relación hora, duración, género y acceso gratuito. Esa es la decisión que una cartelera genérica no resuelve. Si el lector solo dispone de 90 minutos, ninguna de las dos películas largas es una recomendación responsable: conviene usar el filtro de duración de GuíaTV o pasar a una ficha de streaming.</p></section><section><h2>Qué revisar antes de sentarse</h2><p>Las horas de la programación pueden modificarse y una emisión que empieza antes de la consulta puede no estar disponible desde el principio. GuíaTV identifica el canal, la ventana y la duración, pero la cadena sigue siendo la referencia final para cambios de última hora. La fecha de esta selección es 31/08/2026; no debe reciclarse para mañana sin repetir la consulta. El enlace de programación permite sustituir rápidamente un título que ya haya comenzado por la siguiente película confirmada.</p></section>`,
  'series-hoy-en-tv': `<section><h2>Qué series aparecen hoy y a qué hora</h2><p>Para el 31 de agosto de 2026, la EPG de GuíaTV permite separar tres tipos de sesión. Por la tarde, <strong>Valle Salvaje</strong> figura en La 1 a las 17:45, con 50 minutos; después llega <strong>La Promesa</strong> a las 18:35, con una hora prevista. En la noche, Antena 3 programa <strong>En tierra lejana</strong> a las 23:00, con una ventana de 195 minutos. No son equivalentes: las dos primeras sirven para seguir una franja diaria y la última exige reservar buena parte de la noche.</p><p>La ficha de GuíaTV aporta además el tipo de contenido, año, edad orientativa y valoración disponible en el registro. En esta fecha, La Promesa aparece como serie de 2026 con indicación ⑫ y puntuación 7,4/10, mientras que Valle Salvaje figura con indicación ⑫ y 6,0/10. Son señales para ordenar la búsqueda, no una crítica sustitutiva. La recomendación editorial es probar La Promesa si se busca una emisión de una hora y elegir En tierra lejana solo cuando el usuario quiera una sesión extensa.</p></section><section><h2>La mejor elección depende de la sesión</h2><ul><li><strong>Para ver un capítulo sin alargar la noche:</strong> Valle Salvaje, porque la EPG le asigna 50 minutos. Hay que comprobar si el programa es el episodio esperado y si la hora no ha cambiado.</li><li><strong>Para seguir una ficción diaria:</strong> La Promesa ofrece una franja consecutiva de 60 minutos. Es la opción más manejable para quien quiere incorporar la televisión lineal a su rutina.</li><li><strong>Para una sesión larga de prime time:</strong> En tierra lejana ocupa 195 minutos en Antena 3. La duración es el factor decisivo; no es una buena recomendación para quien necesita terminar antes de medianoche.</li></ul><p>Esta lectura evita el error de recomendar una serie solo por su título. La hora de comienzo, la duración y la continuidad cambian la experiencia. Si el lector busca una temporada completa, debe salir de la EPG y abrir la ficha de plataformas: una emisión concreta no demuestra que todos los episodios estén bajo demanda.</p></section><section><h2>Cómo confirmar el capítulo correcto</h2><p>Abre la guía del canal, revisa la ficha del programa y compara la hora local con la hora actual. Si la emisión ya empezó, la recomendación debe decirlo; no hay que presentarla como una opción disponible desde el principio. Para una serie que se repite en varios canales, conserva el registro con mayor detalle de temporada y episodio. La comprobación se realizó con la ventana EPG del 31/08/2026 y debe repetirse en cada nueva edición.</p></section>`,
  'futbol-hoy-en-tv': `<section><h2>Lo que sí aparece confirmado hoy</h2><p>La consulta EPG de GuíaTV para el 31 de agosto de 2026 no permite afirmar que haya un partido de fútbol en directo en cada canal deportivo. Sí muestra contenido futbolístico concreto. En TVGAL.TV aparece <strong>LALIGA HYPERMOTION: RC Celta B - CD Castellón</strong>, con una ventana de 21:25 a 23:26 en hora peninsular al convertir el registro UTC. En los canales de Movistar LaLiga aparecen además la previa y el post de la jornada de Primera, pero una previa o un post no deben venderse como el partido en directo.</p><p>La agenda oficial de LaLiga confirma dos partidos de EA SPORTS para el lunes 31: <strong>CA Osasuna - Getafe CF a las 19:30</strong> y <strong>FC Barcelona - Rayo Vallecano a las 21:30</strong>. La propia página de LaLiga asigna operadores concretos: Movistar LALIGA para el primero y DAZN para el segundo. Esta doble comprobación es importante porque la EPG puede mostrar programas de acompañamiento y los horarios de los canales pueden expresarse en UTC.</p></section><section><h2>Partido, programa y canal no son el mismo dato</h2><table><thead><tr><th>Consulta</th><th>Dato verificado</th><th>Qué debe comprobar el lector</th></tr></thead><tbody><tr><td>Osasuna - Getafe</td><td>19:30 · Movistar LALIGA</td><td>Que su paquete incluya el canal y que la hora no haya cambiado.</td></tr><tr><td>Barcelona - Rayo</td><td>21:30 · DAZN</td><td>Que el plan DAZN contratado incluya LaLiga 2026/27.</td></tr><tr><td>Celta B - Castellón</td><td>Ventana EPG en TVGAL.TV</td><td>Si la emisión es el directo buscado y la cobertura está disponible en su territorio.</td></tr></tbody></table><p>La regla práctica es abrir primero la ficha del encuentro y después la del canal. El nombre “Deportes 2” aparece en numerosas señales de la EPG y no identifica por sí solo una retransmisión. Tampoco basta que un canal se llame LaLiga: hay que unir partido, operador y paquete. GuíaTV aporta el cruce de agenda y programación; la fuente oficial del titular de derechos conserva la última palabra.</p></section><section><h2>Cómo evitar una falsa confirmación</h2><p>Los partidos son especialmente sensibles a cambios de horario, sustituciones y restricciones territoriales. Por eso esta pieza muestra la fecha de verificación junto a la fuente y no congela una lista para días posteriores. Si GuíaTV no devuelve el encuentro o no resuelve el canal, la respuesta correcta es “pendiente de confirmación”, no una plataforma elegida por costumbre. La agenda de fútbol es la ruta interna para repetir la comprobación justo antes del saque inicial.</p></section>`,
  'donde-ver-laliga-en-espana': `<section><h2>La respuesta para la jornada del 31 de agosto</h2><p>Para la jornada 3 de LALIGA EA SPORTS 2026/27, la página oficial de LaLiga publica dos partidos el lunes 31 de agosto. <strong>CA Osasuna - Getafe CF</strong> está fijado a las 19:30 y figura con Movistar LALIGA como operador; <strong>FC Barcelona - Rayo Vallecano</strong> aparece a las 21:30 con DAZN. Son respuestas para partidos concretos, no una afirmación de que cualquiera de los dos servicios emita toda la competición en cualquier plan.</p><p>DAZN explica en su ayuda para la temporada que sus planes Fútbol, Pro y Premium pueden incluir LaLiga 2026/27 y que su paquete ofrece cinco partidos por jornada en 35 de las 38 jornadas, además del partido en abierto de cada jornada. Esa descripción no sustituye la tabla oficial de LaLiga para saber quién emite un encuentro específico. Para el partido de Osasuna hay que comprobar Movistar LALIGA; para Barcelona-Rayo, la ruta de DAZN.</p></section><section><h2>Cómo comprobar el partido correcto</h2><ol><li>Busca los dos equipos en la agenda de fútbol de GuíaTV y confirma fecha, competición y hora española.</li><li>Abre la fuente oficial de LaLiga para verificar el operador asignado a ese encuentro.</li><li>Revisa el plan del proveedor: tener una cuenta o una aplicación instalada no demuestra que el paquete incluya el partido.</li><li>Vuelve a mirar la ficha antes del inicio, porque LaLiga advierte que fechas y horarios pueden modificarse.</li></ol><p>Este proceso es más fiable que una tabla de “derechos” copiada de otra temporada. También evita confundir LALIGA EA SPORTS con LALIGA HYPERMOTION, que tiene una distribución distinta. En GuíaTV, la ficha de partido sirve para pasar de la competición al canal y detectar si la emisión está resuelta o todavía pendiente.</p></section><section><h2>Qué servicio encaja con cada necesidad</h2><p>Si el objetivo inmediato es Osasuna-Getafe, la decisión empieza por Movistar LALIGA, no por una comparativa general de catálogos. Si se quiere ver Barcelona-Rayo, el dato operativo es DAZN y el plan que indique LaLiga 2026/27. Para seguir muchas jornadas, conviene hacer una cesta de partidos favoritos y comparar qué operador cubre realmente esos encuentros; una promesa de “todo el fútbol” no es suficientemente precisa. El coste debe calcularse con la tarifa vigente del proveedor, separando promociones y paquetes de operador.</p><p>La última comprobación editorial de esta guía se hizo el 31/08/2026 con la agenda oficial de LaLiga, la ayuda de DAZN y la EPG de GuíaTV. Los horarios y derechos no deben conservarse sin fecha: la página es útil precisamente porque permite repetir la consulta por partido.</p></section>`,
  'netflix-vs-prime-video-espana': `<section><h2>Dos servicios, dos formas de entender el catálogo</h2><p>Netflix funciona como una suscripción cerrada: sus páginas españolas presentan planes mensuales de 8,99 €, 14,99 € y 21,99 €, con diferencias de anuncios, resolución, pantallas y descargas. Prime Video, en cambio, combina títulos incluidos con alquileres, compras y suscripciones adicionales. La ayuda oficial de Amazon dice expresamente que la selección incluida cambia y que un título alquilado o comprado se cobra aparte. Esta diferencia es más importante que comparar el número de carátulas.</p><p>Para una persona que quiere pulsar reproducir sin revisar etiquetas, Netflix es más sencillo de interpretar, aunque el plan con anuncios puede excluir algunos títulos y todos los catálogos dependen de licencias territoriales. Prime Video puede resultar más flexible para quien alterna suscripción y alquiler, pero exige mirar si la ficha dice “Incluido con Prime”, alquiler, compra o canal adicional. GuíaTV debe conservar esa modalidad en cada ficha y no agruparla como disponibilidad equivalente.</p></section><section><h2>Comparativa práctica para España</h2><table><thead><tr><th>Criterio</th><th>Netflix</th><th>Prime Video</th></tr></thead><tbody><tr><td>Precio de entrada comprobado</td><td>8,99 €/mes con anuncios</td><td>Confirmar en la cuenta/proveedor; no se fija aquí una cifra no publicada en la fuente consultada</td></tr><tr><td>Resolución y pantallas</td><td>Dependen del plan; el Premium llega a 4K HDR y cuatro dispositivos</td><td>Dependen de la modalidad y dispositivo; comprobar la ficha oficial</td></tr><tr><td>Acceso al título</td><td>Normalmente dentro del plan, con excepciones marcadas</td><td>Incluido, alquiler, compra o add-on</td></tr><tr><td>Mejor para</td><td>Descubrimiento guiado y originales</td><td>Quien valora reunir vídeo, alquileres y canales en una misma aplicación</td></tr></tbody></table><p>La tabla no convierte una diferencia de producto en una sentencia universal. Si el lector tiene tres títulos prioritarios, hay que buscarlos en GuíaTV, anotar el proveedor y comprobar el tipo de acceso. Si dos están incluidos en Netflix pero solo alquilados en Prime, el coste real cambia aunque Prime muestre más resultados.</p></section><section><h2>Veredicto editorial</h2><p>Recomendaría Netflix a quien quiere una experiencia predecible y usa descargas, perfiles o recomendaciones con frecuencia. Recomendaría Prime Video a quien ya usa Amazon Prime y acepta separar contenido incluido de transacciones puntuales. En ambos casos, la comprobación final debe hacerse el día de contratación: precio, catálogo y condiciones pueden cambiar. Última verificación: 31/08/2026 con Netflix España, ayuda de Netflix, ayuda de Prime Video y fichas españolas de GuíaTV.</p></section>`,
  'netflix-vs-max-espana': `<section><h2>La elección depende de amplitud frente a selección</h2><p>Netflix publica en España tres niveles reconocibles: 8,99 € con anuncios, 14,99 € estándar y 21,99 € premium en la comprobación de esta guía. El nivel Premium ofrece 4K HDR y cuatro reproducciones simultáneas; el Estándar ofrece 1080p y dos. Max describe una estructura de Básico con anuncios, Estándar y Premium: los dos primeros ofrecen Full HD y dos dispositivos, mientras que Premium llega a 4K UHD, cuatro dispositivos y hasta 100 descargas, sujeto a disponibilidad y restricciones. Max advierte que el precio depende del proveedor y el plan, así que no se le asigna una cifra sin confirmar la venta española concreta.</p><p>Netflix suele ser la opción más fácil para quien quiere amplitud, novedades frecuentes y una aplicación que decide por él. Max tiene más sentido cuando el lector busca el ecosistema HBO, Warner Bros., DC, Cartoon Network o cine de catálogo y acepta comparar su plan y proveedor. Son perfiles editoriales, no estadísticas de tamaño: GuíaTV debe demostrar la recomendación con títulos concretos comprobados en España.</p></section><section><h2>Cómo hacer una cesta de decisión</h2><ol><li>Escribe tres películas y tres series que realmente verías durante el mes.</li><li>Busca cada título en GuíaTV y anota si aparece en Netflix, Max, en ambos o en ninguno.</li><li>Separa la disponibilidad del precio: que una ficha exista no demuestra que el título esté incluido en todos los planes.</li><li>Calcula el coste de un mes normal, sin promociones temporales, y añade el valor de 4K, descargas o pantallas solo si vas a usarlos.</li></ol><p>Este método evita el error de declarar ganador al servicio con la lista más larga. También evita pagar Premium por una televisión que solo reproduce 1080p. Si la cesta queda empatada, la mejor decisión es rotar: contratar un servicio durante el mes de sus títulos prioritarios y cancelar cuando la fuente confirme que ya no compensa.</p></section><section><h2>Conclusión</h2><p>Netflix es mi elección general para quien empieza desde cero y quiere una experiencia sencilla; Max es mi elección para quien ya sabe que busca ficción de HBO/Warner o un catálogo cinematográfico concreto. El lector puede comprobar ambas rutas desde las fichas de GuíaTV. Verificación factual: 31/08/2026; fuentes: Netflix España, ayuda de Netflix, ayuda de Max y catálogo español de GuíaTV.</p></section>`,
  'max-vs-disney-plus-espana': `<section><h2>La diferencia útil está en el hogar y los títulos</h2><p>Disney+ España publica tres planes: Estándar con anuncios por 6,99 €/mes, Estándar por 10,99 €/mes y Premium por 15,99 €/mes. El primero ofrece hasta 1080p y dos reproducciones simultáneas; el Estándar mantiene 1080p y dos; Premium llega a 4K HDR y cuatro, con descargas y Dolby Atmos según las condiciones publicadas. Max describe Básico con anuncios, Estándar y Premium, pero remite a max.com para el precio porque puede variar por proveedor. Esa diferencia de transparencia obliga a no rellenar la comparativa con una tarifa antigua.</p><p>Disney+ es una recomendación lógica cuando las prioridades están en sus marcas familiares y de franquicia y el hogar necesita controles y perfiles adaptados a edades distintas. Max encaja mejor con quien busca HBO, Warner Bros., DC, Cartoon Network, documentales, reality o cine adulto. La clasificación no es un juicio de calidad: es una forma de evitar que una familia compre un servicio por la marca y descubra después que sus títulos prioritarios están en el rival.</p></section><section><h2>Qué plan pagar</h2><table><thead><tr><th>Perfil</th><th>Opción a estudiar</th><th>Razón</th></tr></thead><tbody><tr><td>Presupuesto mínimo familiar</td><td>Disney+ Estándar con anuncios</td><td>6,99 €/mes, 1080p y dos reproducciones según la página española.</td></tr><tr><td>Dos espectadores sin anuncios en Disney+</td><td>Disney+ Estándar</td><td>10,99 €/mes y dos reproducciones; la calidad máxima publicada es 1080p.</td></tr><tr><td>Televisor 4K y varios usuarios</td><td>Comparar Premium de ambos</td><td>Disney+ publica 15,99 €; Max requiere confirmar proveedor y precio.</td></tr><tr><td>Catálogo HBO/Warner como prioridad</td><td>Max</td><td>La decisión depende de que los títulos buscados estén incluidos en España.</td></tr></tbody></table><p>La cesta de títulos se comprueba en GuíaTV antes del pago. Dos servicios pueden compartir una película temporalmente y diferir en series; por eso el lector debe anotar la fecha y no tratar la disponibilidad como permanente.</p></section><section><h2>Veredicto</h2><p>Disney+ gana para un hogar que valora su catálogo familiar y quiere un precio español visible por nivel. Max gana para una lista centrada en HBO, Warner o DC. Si no hay una prioridad clara, el plan Disney+ con anuncios es el punto de entrada cuantificable, pero no debe llamarse mejor sin comprobar anuncios, pantallas y títulos. Última verificación: 31/08/2026.</p></section>`,
  'movistar-plus-vs-dazn': `<section><h2>Compara competiciones, no logotipos</h2><p>Movistar Plus+ y DAZN no se pueden ordenar con una lista única de “deporte incluido”. La fuente oficial de LaLiga para la jornada 3 de 2026/27 asigna CA Osasuna-Getafe a Movistar LALIGA y FC Barcelona-Rayo Vallecano a DAZN el 31 de agosto. DAZN, además, explica que sus planes Fútbol, Pro y Premium pueden incluir LaLiga 2026/27, con cinco partidos por jornada en 35 de las 38 jornadas y el partido en abierto de cada jornada. La cifra describe el paquete de derechos de DAZN, no una garantía de que el plan que el lector ve en una oferta concreta sea el adecuado.</p><p>Movistar Plus+ tiene valor cuando el usuario ya dispone del operador o necesita el canal Movistar LALIGA para encuentros que LaLiga asigna allí. DAZN es más directo para quien quiere una suscripción deportiva independiente y sus competiciones anunciadas, pero también hay que comprobar si el encuentro está dentro del plan contratado. Los dos casos exigen separar acceso directo, paquete de telecomunicaciones, canal lineal y promoción.</p></section><section><h2>Una comprobación reproducible</h2><ol><li>Lista los partidos y competiciones que verías durante el mes, no “todo el fútbol”.</li><li>Busca cada encuentro en la agenda de GuíaTV y conserva la fecha, hora y canal resueltos.</li><li>Contrasta la asignación con la página oficial de LaLiga, que avisa de posibles cambios.</li><li>Abre la oferta del proveedor y confirma que el nombre del plan menciona la competición.</li><li>Compara el coste normal de un mes con la duración de la temporada; no anualices una promoción sin condiciones.</li></ol><p>En la ficha de GuíaTV, un programa de previa o postpartido no debe contarse como emisión del encuentro. Tampoco un canal llamado “Deportes” prueba que emita LaLiga. La aportación editorial consiste en unir el partido concreto con su operador y exponer cuándo el dato necesita una nueva comprobación.</p></section><section><h2>Conclusión práctica</h2><p>Para Osasuna-Getafe, la fuente del día apunta a Movistar LALIGA; para Barcelona-Rayo, apunta a DAZN. Para elegir una suscripción mensual, gana el servicio que cubra la cesta real de partidos del lector al coste y condiciones que muestra su propia página. Verificación: 31/08/2026 con LaLiga, DAZN y la agenda deportiva de GuíaTV.</p></section>`,
  'mejores-plataformas-para-peliculas': `<section><h2>Qué plataforma elegir según el tipo de cine</h2><p>El catálogo consultado de GuíaTV muestra por qué no sirve sumar carátulas sin mirar el tipo de acceso. En Netflix aparecen <strong>Intercambiados</strong>, <strong>La captura</strong> y <strong>El caballero oscuro</strong>; en Prime Video aparecen <strong>Proyecto Salvación</strong>, <strong>El caballero oscuro</strong>, <strong>Interstellar</strong> y <strong>Origen</strong>; en Max aparecen <strong>Cadena perpetua</strong>, <strong>El caballero oscuro</strong>, <strong>Interstellar</strong> y <strong>Spider-Man: un nuevo universo</strong>. Son resultados de la consulta de GuíaTV del 31/08/2026 y deben volver a comprobarse porque el catálogo cambia.</p><table><thead><tr><th>Si buscas...</th><th>Empezaría por...</th><th>Por qué</th></tr></thead><tbody><tr><td>Ciencia ficción accesible</td><td>Prime Video</td><td>La consulta devuelve Proyecto Salvación, Interstellar y Origen; revisa en cada ficha si el acceso es incluido.</td></tr><tr><td>Cine clásico muy valorado</td><td>Max</td><td>Cadena perpetua aparece en el catálogo consultado y permite una sesión de drama carcelario.</td></tr><tr><td>Superhéroes y animación</td><td>Max</td><td>La búsqueda devuelve Spider-Man: un nuevo universo; comprueba plan y disponibilidad.</td></tr><tr><td>Descubrimiento general</td><td>Netflix</td><td>Su interfaz y catálogo de películas son el criterio; la elección final depende de tus títulos prioritarios.</td></tr></tbody></table></section><section><h2>Cómo valorar cada recomendación</h2><p>Una plataforma de cine gana cuando reúne al menos tres películas que verías ahora, no cuando tiene una cifra total que nadie puede auditar. GuíaTV permite buscar por servicio y abrir la ficha para revisar título, año, género, sinopsis y modalidad. Prime Video exige especial cuidado: Amazon distingue incluido con Prime, alquiler, compra y suscripción adicional. Si una película solo aparece como alquiler, cuenta ese coste como una compra puntual, no como catálogo incluido.</p><p>Filmin no se incluye en la tabla por falta de una muestra verificada en esta consulta; esa ausencia es preferible a inventar una ventaja. Para comparar Netflix, Prime Video y Max, usa la misma cesta de cinco películas y anota la fecha. El resultado será más útil que decir que una plataforma es “la mejor” para todos.</p></section>`,
  'mejores-plataformas-para-series': `<section><h2>Resultados actuales del catálogo español</h2><p>La consulta de GuíaTV del 31/08/2026 devuelve perfiles reconocibles. Netflix incluye en sus resultados <strong>Breaking Bad</strong>, <strong>Rick y Morty</strong>, <strong>The Office</strong>, <strong>House</strong>, <strong>The Rookie</strong> y <strong>El mentalista</strong>. Prime Video muestra <strong>The Office</strong>, <strong>El mentalista</strong>, <strong>Ted Lasso</strong>, <strong>Sobrenatural</strong>, <strong>Shameless</strong> y <strong>Smallville</strong>. Max devuelve <strong>Rick y Morty</strong>, <strong>From</strong>, <strong>Juego de tronos</strong>, <strong>El mentalista</strong> y <strong>La casa del dragón</strong>. La selección no significa que cada título esté incluido en todos los planes: la ficha de acceso es la comprobación final.</p><table><thead><tr><th>Perfil</th><th>Mejor punto de partida</th><th>Ejemplos verificados</th></tr></thead><tbody><tr><td>Drama de largo recorrido</td><td>Netflix</td><td>Breaking Bad, House y El mentalista.</td></tr><tr><td>Comedia y animación</td><td>Netflix o Max</td><td>Rick y Morty aparece en ambos resultados.</td></tr><tr><td>Fantasía y drama premium</td><td>Max</td><td>Juego de tronos, From y La casa del dragón.</td></tr><tr><td>Catálogo amplio de temporadas</td><td>Prime Video</td><td>Sobrenatural, Shameless y Smallville.</td></tr></tbody></table></section><section><h2>La continuidad cambia el valor</h2><p>En series, no basta con encontrar el nombre. Comprueba si la ficha representa la serie completa, qué temporadas están disponibles y si el acceso es parte de la suscripción. Una serie que exige un canal adicional puede dejar de ser la opción barata aunque se descubra dentro de la aplicación. GuíaTV aporta una ruta reproducible: filtra por plataforma, abre la serie, anota las temporadas y compárala con dos alternativas del mismo género.</p><p>Mi recomendación es elegir una plataforma por la combinación de una serie larga, una temporada corta y una opción para compartir. Netflix ofrece una cesta fuerte de dramas y comedias; Max destaca en ficción de HBO/Warner y Prime Video en amplitud de temporadas. Es una conclusión editorial basada en la muestra actual, no una medición universal de calidad. Repite la búsqueda antes de publicar una actualización.</p></section>`,
  'mejor-plataforma-streaming-familias': `<section><h2>Qué debe comprobar una familia</h2><p>El precio de entrada no resuelve una decisión familiar. Disney+ España publica Estándar con anuncios por 6,99 €/mes, Estándar por 10,99 € y Premium por 15,99 €; los planes de 6,99 € y 10,99 € ofrecen 1080p y dos reproducciones simultáneas, mientras que Premium llega a 4K HDR y cuatro. Netflix explica que ofrece perfiles infantiles y controles, y su plan con anuncios puede tener títulos no disponibles. Prime Video combina incluidos, alquileres, compras y add-ons. Cada dato debe leerse junto a la edad del espectador y al número de pantallas reales del hogar.</p><table><thead><tr><th>Necesidad</th><th>Decisión razonable</th><th>Comprobación</th></tr></thead><tbody><tr><td>Presupuesto bajo</td><td>Disney+ con anuncios</td><td>6,99 €/mes, 1080p y dos reproducciones; aceptar publicidad.</td></tr><tr><td>Dos pantallas sin anuncios</td><td>Disney+ Estándar</td><td>10,99 €/mes y 1080p; comprobar catálogo familiar.</td></tr><tr><td>Televisor 4K y cuatro usuarios</td><td>Disney+ Premium o Max Premium</td><td>Comparar 4K, descargas y precio vigente del proveedor.</td></tr><tr><td>Edades muy distintas</td><td>Netflix o combinación rotatoria</td><td>Revisar perfiles, control infantil y títulos concretos en GuíaTV.</td></tr></tbody></table></section><section><h2>Cómo construir una lista por edades</h2><p>Empieza por tres grupos: una película para ver juntos, una serie que puedan seguir los adultos y una alternativa para la franja infantil. Búscalos en GuíaTV y revisa clasificación, duración y plataforma española. No uses “familiar” como sinónimo de apto para cualquier edad: la ficha y la clasificación son la referencia práctica. Tampoco compartas credenciales entre hogares asumiendo que está permitido; las condiciones del proveedor mandan.</p><p>Disney+ es mi primera opción cuando la prioridad son sus franquicias familiares y un plan español claro. Netflix es más versátil si el hogar combina edades y quiere perfiles infantiles. Prime Video puede tener buen valor cuando ya se dispone de Prime, pero exige distinguir los títulos incluidos de alquileres. Verificado el 31/08/2026 con Disney+, Netflix, Prime Video y catálogo de GuíaTV.</p></section>`,
  'streaming-por-menos-de-10-euros': `<section><h2>Las opciones comprobadas por debajo del límite</h2><p>En España, la comprobación del 31/08/2026 deja dos entradas claras por debajo de 10 €: Netflix Estándar con anuncios por 8,99 €/mes y Disney+ Estándar con anuncios por 6,99 €/mes. Netflix indica 1080p y dos reproducciones para su plan con anuncios; Disney+ publica 1080p y dos reproducciones para el suyo. No son planes sin publicidad ni promesas de catálogo completo. Netflix también advierte que algunos títulos pueden quedar bloqueados por licencia, y Disney+ explica que ciertos anuncios/promociones pueden aparecer según el contexto.</p><table><thead><tr><th>Plan</th><th>Precio mensual</th><th>Incluye según fuente</th><th>Renuncia</th></tr></thead><tbody><tr><td>Disney+ Estándar con anuncios</td><td>6,99 €</td><td>1080p, dos reproducciones</td><td>Anuncios</td></tr><tr><td>Netflix Estándar con anuncios</td><td>8,99 €</td><td>1080p, dos reproducciones y descargas según plan</td><td>Algunos títulos pueden no estar disponibles</td></tr></tbody></table></section><section><h2>El precio no es el coste de la sesión</h2><p>Con una sola plataforma, el gasto anualizado de doce meses sería 83,88 € en Disney+ con anuncios y 107,88 € en Netflix con anuncios, si los precios permanecieran iguales; esa hipótesis no sustituye al precio vigente de cada renovación. Si solo quieres ver una serie o una película concreta, la rotación mensual puede reducir el gasto, pero debes revisar que el contenido siga disponible cuando contrates. En Prime Video, un alquiler puede quedar por debajo de 10 € y aun así no ser una suscripción; no debe mezclarse en esta tabla.</p><p>Antes de contratar, abre la cesta de títulos en GuíaTV, verifica el servicio español y decide si toleras anuncios. Para una familia, añade el número de reproducciones y perfiles; para una televisión 4K, un plan 1080p puede no satisfacer la necesidad aunque sea barato. La opción más económica es Disney+ con anuncios; la alternativa más cercana es Netflix con anuncios. Ambas conclusiones llevan fecha y deben volver a comprobarse.</p></section>`,
};

